import styled from '@emotion/styled';

export const StyledCard = styled.div({
  display: 'flex',
  flexDirection: 'column',
  border: 'none',
  borderRadius: '16px',
  width: '100%',
  minWidth: '205px',
  maxWidth: '230px',
  height: '100%',
  minHeight: '323px',
  maxHeight: '339.4px',
  backgroundColor: '#FFFFFF',
  cursor: 'pointer',
  transition: 'transform 0.25s ease-in-out',
  '&:hover': {
    transform: 'scale(1.05)',
  },
});

export const StyledCardImage = styled.img({
  width: '100%',
  height: '208px',
  objectFit: 'cover',
  borderRadius: '16px 16px 0 0',
});

export const StyledContentWrapper = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '8px',
  padding: '16px 16px 0 16px',
  fontFamily: 'Barlow',
});

export const StyledCardContent = styled.div({
  height: '60px',
  display: 'flex',
  flexDirection: 'column',
  gap: '8px',
});

export const StyledCardTitle = styled.h3({
  fontFamily: 'Barlow',
  fontWeight: '600',
  fontStyle: 'SemiBold',
  fontSize: '16px',
  lineHeight: '120%',
  letterSpacing: '0%',
  textAlign: 'start',
  margin: '0',
});

export const StyledTagContainer = styled.div({
  display: 'flex',
  flexWrap: 'wrap',
  flexDirection: 'row',
  gap: '4px',
  height: 'max-content',
});

export const StyledCardTag = styled.div({
  width: 'max-content',
  maxWidth: '112px',
  height: '24px',
  borderRadius: '4px',
  borderWidth: '1px',
  padding: '4px 6px',
  backgroundColor: '#F2F2F2',
  fontFamily: 'Work Sans',
  fontWeight: '400',
  fontStyle: 'Regular',
  fontSize: '12px',
  lineHeight: '120%',
  letterSpacing: '0%',
  textAlign: 'center',
  whiteSpace: 'nowrap',
  overflow: 'hidden',
  textOverflow: 'ellipsis',
});

export const StyledLink = styled.p({
  color: '#006EDB',
  fontFamily: 'Work Sans',
  fontWeight: '500',
  fontStyle: 'Medium',
  fontSize: '12px',
  lineHeight: '16px',
  letterSpacing: '0%',
  textDecoration: 'underline',
  textDecorationStyle: 'solid',
  textAlign: 'end',
  margin: '0',
});
